class Solution {
    int prev = 0, run = 0, best = 0;
    bool hasPrev = false;
    std::vector<int> result;
    void dfs(TreeNode* node) {
        if (!node) return;
        dfs(node->left);
        if (hasPrev && prev == node->val) ++run;
        else run = 1;
        prev = node->val;
        hasPrev = true;
        if (run > best) { best = run; result.clear(); }
        if (run == best) result.push_back(node->val);
        dfs(node->right);
    }
public:
    std::vector<int> findMode(TreeNode* root) {
        prev = run = best = 0;
        hasPrev = false;
        result.clear();
        dfs(root);
        return result;
    }
};
